SELECT * FROM reservations r
JOIN rooms rm ON r.room_id = rm.room_id
WHERE rm.accommodation_id = #{accommodationId}

mapper.update:
UPDATE reservations
SET status = #{status}, updated_at = NOW()
WHERE reservation_id = #{reservationId}

UPDATE reservations
SET payment_status = #{paymentStatus}, updated_at = NOW()
WHERE reservation_id = #{reservationId}

UPDATE reservations
SET status = 'CANCELLED', updated_at = NOW()
WHERE reservation_id = #{reservationId}

mapper.select:
SELECT
    reservation_id, user_id, room_id, check_in_date, check_out_date, guest_count,
    total_price, status, payment_status, special_requests, created_at, updated_at
FROM reservations


        AND user_id = #{userId}


        AND room_id = #{roomId}


        AND status = #{status}


        AND payment_status = #{paymentStatus}


        AND check_in_date >= #{startDate}


        AND check_out_date <= #{endDate}



ORDER BY created_at DESC

SELECT EXISTS (
    SELECT 1
    FROM reservations r
    JOIN rooms rm ON r.room_id = rm.room_id
    WHERE r.user_id = #{userId}
    AND rm.accommodation_id = #{accommodationId}
    AND r.status = 'COMPLETED' 
    AND r.check_out_date < CURDATE() 
)
